    14→
    15→// Hook marker used to identify Entire CLI hooks
    16→const entireHookMarker = "Entire CLI hooks"
    17→
    18→// gitHookNames are the git hooks managed by Entire CLI
    19→var gitHookNames = []string{"prepare-commit-msg", "commit-msg", "post-commit", "pre-push"}
    20→
    21→// GetGitDir returns the actual git directory path by delegating to git itself.
    22→// This handles both regular repositories and worktrees, and inherits git's
    23→// security validation for gitdir references.
    24→func GetGitDir() (string, error) {
    25→	return getGitDirInPath(".")
    26→}
    27→
    28→// getGitDirInPath returns the git directory for a repository at the given path.
    29→// It delegates to `git rev-parse --git-dir` to leverage git's own validation.
    30→func getGitDirInPath(dir string) (string, error) {
    31→	ctx := context.Background()
    32→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-dir")
    33→	cmd.Dir = dir
    34→	output, err := cmd.Output()
    35→	if err != nil {
    36→		return "", errors.New("not a git repository")
    37→	}
    38→
    39→	gitDir := strings.TrimSpace(string(output))
    40→
    41→	// git rev-parse --git-dir returns relative paths from the working directory,
    42→	// so we need to make it absolute if it isn't already
    43→	if !filepath.IsAbs(gitDir) {
    44→		gitDir = filepath.Join(dir, gitDir)
    45→	}
    46→
    47→	return filepath.Clean(gitDir), nil
    48→}
    49→
    50→// IsGitHookInstalled checks if all generic Entire CLI hooks are installed.
    51→func IsGitHookInstalled() bool {
    52→	gitDir, err := GetGitDir()
    53→	if err != nil {
    54→		return false
    55→	}
    56→	for _, hook := range gitHookNames {
    57→		hookPath := filepath.Join(gitDir, "hooks", hook)
    58→		data, err := os.ReadFile(hookPath) //nolint:gosec // Path is constructed from constants
    59→		if err != nil {
    60→			return false
    61→		}
    62→		if !strings.Contains(string(data), entireHookMarker) {
    63→			return false
    64→		}
    65→	}
    66→	return true
    67→}
    68→
    69→// InstallGitHook installs generic git hooks that delegate to `entire hook` commands.
    70→// These hooks work with any strategy - the strategy is determined at runtime.
    71→// If silent is true, no output is printed.
    72→// Returns the number of hooks that were installed (0 if all already up to date).
    73→func InstallGitHook(silent bool) (int, error) {
    74→	gitDir, err := GetGitDir()
    75→	if err != nil {
    76→		return 0, err
    77→	}
    78→
    79→	hooksDir := filepath.Join(gitDir, "hooks")
    80→	if err := os.MkdirAll(hooksDir, 0o755); err != nil { //nolint:gosec // Git hooks require executable permissions
    81→		return 0, fmt.Errorf("failed to create hooks directory: %w", err)
    82→	}
    83→
    84→	// Determine command prefix based on local_dev setting
    85→	var cmdPrefix string
    86→	if isLocalDev() {
    87→		cmdPrefix = "go run ./cmd/entire/main.go"
    88→	} else {
    89→		cmdPrefix = "entire"
    90→	}
    91→
    92→	installedCount := 0
    93→
    94→	// Install prepare-commit-msg hook
    95→	// $1 = commit message file, $2 = source (message, template, merge, squash, commit, or empty)
    96→	prepareCommitMsgPath := filepath.Join(hooksDir, "prepare-commit-msg")
    97→	prepareCommitMsgContent := fmt.Sprintf(`#!/bin/sh
    98→# %s
    99→%s hooks git prepare-commit-msg "$1" "$2" 2>/dev/null || true
   100→`, entireHookMarker, cmdPrefix)
   101→
   102→	written, err := writeHookFile(prepareCommitMsgPath, prepareCommitMsgContent)
   103→	if err != nil {
   104→		return 0, fmt.Errorf("failed to install prepare-commit-msg hook: %w", err)
   105→	}
   106→	if written {
   107→		installedCount++
   108→	}
   109→
   110→	// Install commit-msg hook
   111→	commitMsgPath := filepath.Join(hooksDir, "commit-msg")
   112→	commitMsgContent := fmt.Sprintf(`#!/bin/sh
   113→# %s
   114→# Commit-msg hook: strip trailer if no user content (allows aborting empty commits)
   115→%s hooks git commit-msg "$1" || exit 1
   116→`, entireHookMarker, cmdPrefix)
   117→
   118→	written, err = writeHookFile(commitMsgPath, commitMsgContent)
   119→	if err != nil {
   120→		return 0, fmt.Errorf("failed to install commit-msg hook: %w", err)
   121→	}
   122→	if written {
   123→		installedCount++
   124→	}
   125→
   126→	// Install post-commit hook
   127→	postCommitPath := filepath.Join(hooksDir, "post-commit")
   128→	postCommitContent := fmt.Sprintf(`#!/bin/sh
   129→# %s
   130→# Post-commit hook: condense session data if commit has Entire-Checkpoint trailer
   131→%s hooks git post-commit 2>/dev/null || true
   132→`, entireHookMarker, cmdPrefix)
   133→
   134→	written, err = writeHookFile(postCommitPath, postCommitContent)
   135→	if err != nil {
   136→		return 0, fmt.Errorf("failed to install post-commit hook: %w", err)
   137→	}
   138→	if written {
   139→		installedCount++
   140→	}
   141→
   142→	// Install pre-push hook
   143→	prePushPath := filepath.Join(hooksDir, "pre-push")
   144→	prePushContent := fmt.Sprintf(`#!/bin/sh
   145→# %s
   146→# Pre-push hook: push session logs alongside user's push
   147→# $1 is the remote name (e.g., "origin")
   148→%s hooks git pre-push "$1" || true
   149→`, entireHookMarker, cmdPrefix)
   150→
   151→	written, err = writeHookFile(prePushPath, prePushContent)
   152→	if err != nil {
   153→		return 0, fmt.Errorf("failed to install pre-push hook: %w", err)
   154→	}
   155→	if written {
   156→		installedCount++
   157→	}
   158→
   159→	if !silent {
   160→		fmt.Println("✓ Installed git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
   161→		fmt.Println("  Hooks delegate to the current strategy at runtime")
   162→	}
   163→
   164→	return installedCount, nil
   165→}
