   167→// writeHookFile writes a hook file if it doesn't exist or has different content.
   168→// Returns true if the file was written, false if it already had the same content.
   169→func writeHookFile(path, content string) (bool, error) {
   170→	// Check if file already exists with same content
   171→	existing, err := os.ReadFile(path) //nolint:gosec // path is controlled
   172→	if err == nil && string(existing) == content {
   173→		return false, nil // Already up to date
   174→	}
   175→
   176→	// Git hooks must be executable (0o755)
   177→	if err := os.WriteFile(path, []byte(content), 0o755); err != nil { //nolint:gosec // Git hooks require executable permissions
   178→		return false, fmt.Errorf("failed to write hook file %s: %w", path, err)
   179→	}
   180→	return true, nil
   181→}
   182→
   183→// RemoveGitHook removes all Entire CLI git hooks from the repository.
   184→// Returns the number of hooks removed.
   185→func RemoveGitHook() (int, error) {
   186→	gitDir, err := GetGitDir()
   187→	if err != nil {
   188→		return 0, err
   189→	}
   190→
   191→	removed := 0
   192→	var removeErrors []string
   193→
   194→	for _, hook := range gitHookNames {
   195→		hookPath := filepath.Join(gitDir, "hooks", hook)
   196→		data, err := os.ReadFile(hookPath) //nolint:gosec // path is controlled
   197→		if err != nil {
   198→			continue // Hook doesn't exist
   199→		}
   200→
   201→		if strings.Contains(string(data), entireHookMarker) {
   202→			if err := os.Remove(hookPath); err != nil {
   203→				removeErrors = append(removeErrors, fmt.Sprintf("%s: %v", hook, err))
   204→			} else {
   205→				removed++
   206→			}
   207→		}
   208→	}
   209→
   210→	if len(removeErrors) > 0 {
   211→		return removed, fmt.Errorf("failed to remove hooks: %s", strings.Join(removeErrors, "; "))
   212→	}
   213→	return removed, nil
   214→}
   215→
   216→// isLocalDev reads the local_dev setting from .entire/settings.json
   217→// Works correctly from any subdirectory within the repository.
   218→func isLocalDev() bool {
   219→	s, err := settings.Load()
   220→	if err != nil {
   221→		return false
   222→	}
   223→	return s.LocalDev
   224→}
