    14→func TestGetGitDirInPath_RegularRepo(t *testing.T) {
    15→	// Create a temp directory and initialize a real git repo
    16→	tmpDir := t.TempDir()
    17→
    18→	ctx := context.Background()
    19→	cmd := exec.CommandContext(ctx, "git", "init")
    20→	cmd.Dir = tmpDir
    21→	if err := cmd.Run(); err != nil {
    22→		t.Fatalf("failed to init git repo: %v", err)
    23→	}
    24→
    25→	result, err := getGitDirInPath(tmpDir)
    26→	if err != nil {
    27→		t.Fatalf("unexpected error: %v", err)
    28→	}
    29→
    30→	expected := filepath.Join(tmpDir, ".git")
    31→
    32→	// Resolve symlinks for comparison (macOS /var -> /private/var)
    33→	resultResolved, err := filepath.EvalSymlinks(result)
    34→	if err != nil {
    35→		t.Fatalf("failed to resolve symlinks for result: %v", err)
    36→	}
    37→	expectedResolved, err := filepath.EvalSymlinks(expected)
    38→	if err != nil {
    39→		t.Fatalf("failed to resolve symlinks for expected: %v", err)
    40→	}
    41→
    42→	if resultResolved != expectedResolved {
    43→		t.Errorf("expected %s, got %s", expectedResolved, resultResolved)
    44→	}
    45→}
